// Turn the incoming text into a menu choice. Groups and non-text messages are skipped.
const COOLDOWN_HOURS = 1; // the menu is offered again to the same person only after this pause
const MAX_ANSWERS = 6;    // never more than this many answers an hour to one person: two auto-responders cannot talk to each other forever
const MAX_ALL = 60;       // and never more than this many an hour in all, so a flood cannot use up your message allowance

const event = msg.payload;
if ((event.type !== 'message.received' && event.type !== 'message.replied') || (event.data || {}).direction !== 'inbound') {
    return null;
}
const data = event.data || {};
const sender = data.from || {};
if ((data.to && data.to.group_id) || !sender.number || data.content_type !== 'text') {
    return null;
}
const text = String(data.preview || '').trim().toLowerCase();
let choice = '';
if (text === '1' || text.includes('hours')) choice = '1';
else if (text === '2' || text.includes('address')) choice = '2';
else if (text === '3' || text.includes('person')) choice = '3';
const now = new Date(event.created_at || Date.now()).getTime();
const hourAgo = now - 3600 * 1000;
const menuAt = flow.get('menuAt') || {};
const sentTo = flow.get('sentTo') || {};
const recent = (sentTo[sender.number] || []).filter((t) => t > hourAgo);
const sentAll = (flow.get('sentAll') || []).filter((t) => t > hourAgo);
if (recent.length >= MAX_ANSWERS || sentAll.length >= MAX_ALL) {
    return null;
}
if (choice === '' && now - (menuAt[sender.number] || 0) < COOLDOWN_HOURS * 3600 * 1000) {
    return null;
}
if (choice === '') {
    menuAt[sender.number] = now;
    flow.set('menuAt', menuAt);
}
recent.push(now);
sentAll.push(now);
sentTo[sender.number] = recent;
flow.set('sentTo', sentTo);
flow.set('sentAll', sentAll);
msg.to = '+' + sender.number;
msg.number = event.number_alias || 'main';
msg.choice = choice;
return msg;
